    async def _maybe_confirm_destructive_slash(
        self, *, event: MessageEvent, command: str, title: str, detail: str, execute
    ) -> Union[str, "EphemeralReply", None]:
        """Gate a destructive session slash command (/new, /reset, /undo).

        ``execute()`` (async → str | EphemeralReply) runs immediately when
        ``approvals.destructive_slash_confirm`` is off; otherwise via ``_request_slash_confirm``:
        ``once`` runs it, ``always`` persists the opt-out then runs it, ``cancel`` skips it.
        """
        confirm_required = True
        try:
            approvals = self._read_user_config().get("approvals")
            if isinstance(approvals, dict):
                confirm_required = bool(approvals.get("destructive_slash_confirm", True))
        except Exception:
            pass
        if not confirm_required:
            return await execute()

        session_key = self._session_key_for_source(event.source)

        async def _on_confirm(choice: str):
            # Via the class, not ``self``: tests drive this gate on a bare SimpleNamespace runner.
            return await GatewayBusySessionMixin._run_confirmed_destructive_slash(
                choice, command, execute, session_key
            )

        _p = self._typed_command_prefix_for(event.source.platform)
        prompt_message = (
            f"⚠️ **Confirm /{command}**\n\n"
            f"{detail}\n\n"
            "Choose:\n"
            "• **Approve Once** — proceed this time only\n"
            "• **Always Approve** — proceed and silence this prompt permanently\n"
            "• **Cancel** — keep current conversation\n\n"
            f"_Text fallback: reply `{_p}approve`, `{_p}always`, or `{_p}cancel`._"
        )
        return await self._request_slash_confirm(
            event=event, command=command, title=title, message=prompt_message, handler=_on_confirm
        )

    _DESTRUCTIVE_OPTOUT_NOTE = {
        True: (
            "\n\nℹ️ Future /clear, /new, /reset, and /undo will run "
            "without confirmation. Re-enable via "
            "`approvals.destructive_slash_confirm: true` in config.yaml."
        ),
        # The user did approve this run, so the action still goes ahead, but the preference did
        # not stick and the prompt will be back next time. Say so rather than promising an
        # opt-out that was never written.
        False: (
            "\n\n⚠️ Could not save that preference (config.yaml is not "
            "writable), so /clear, /new, /reset, and /undo will ask "
            "again next time. To silence it permanently, set "
            "`approvals.destructive_slash_confirm: false` in config.yaml."
        ),
    }

    @staticmethod
    async def _run_confirmed_destructive_slash(choice: str, command: str, execute, session_key: str):
        """Confirm-callback body: ``cancel`` → message; ``always`` persists the opt-out, then runs."""
        if choice == "cancel":
            return f"🟡 /{command} cancelled. Conversation unchanged."
        persisted = False
        if choice == "always":
            try:
                from cli import save_config_value
                # save_config_value swallows its own errors and reports the outcome in the return
                # value, so the try block alone says nothing about whether the write landed.
                persisted = bool(save_config_value("approvals.destructive_slash_confirm", False))
                if persisted:
                    logger.info("User opted out of destructive slash confirm (session=%s)", session_key)
                else:
                    logger.warning(
                        "Could not persist destructive_slash_confirm=false "
                        "(session=%s); config.yaml is not writable", session_key,
                    )
            except Exception as exc:
                logger.warning("Failed to persist destructive_slash_confirm=false: %s", exc)
        result = await execute()
        # Only plain-string results get the note: it would mangle an EphemeralReply.
        if choice == "always" and isinstance(result, str):
            return result + GatewayBusySessionMixin._DESTRUCTIVE_OPTOUT_NOTE[persisted]
        return result

    async def _request_slash_confirm(
        self, *, event: MessageEvent, command: str, title: str, message: str, handler
    ) -> Optional[str]:
        """Ask the user to confirm a slash command; ``handler(choice)`` runs on "once"/"always"/
        "cancel" and its return is sent as a message. Returns None if buttons rendered, else the
        text-fallback message (which IS the ack)."""
        from tools import slash_confirm as _slash_confirm_mod
        source = event.source
        session_key = self._session_key_for_source(source)
        # object.__new__ test runners lack the counter; fall back to a local one.
        counter = getattr(self, "_slash_confirm_counter", None)
        if counter is None:
            import itertools as _itertools
            counter = self._slash_confirm_counter = _itertools.count(1)
        confirm_id = f"{next(counter)}"

        # Register FIRST so a fast button click cannot race the send_slash_confirm return.
        _slash_confirm_mod.register(session_key, confirm_id, command, handler)

        adapter = self._delivery_adapter_for(source)
        metadata = self._thread_metadata_for_source(source, self._reply_anchor_for_event(event))

        if adapter is not None:
            try:
                button_result = await adapter.send_slash_confirm(
                    chat_id=source.chat_id, title=title, message=message, session_key=session_key,
                    confirm_id=confirm_id, metadata=metadata,
                )
                if button_result and getattr(button_result, "success", False):
                    return None  # buttons rendered — no redundant text ack
                # P5(b): distinguish a connector egress DECLINE from a lane
                # failure. On a decline the connector refused this destination,
                # so returning `message` as the direct reply would deliver the
                # very content it refused, as text, to the same chat. Suppress
                # the fallback and tear down the registration — no card
                # rendered, so a later reply must not be captured as an answer
                # to an invisible prompt.
                #
                # Classify the STRUCTURED response (see _approval_send_outcome):
                # a code-only decline has no marker colon in its rendered text,
                # and an ambiguous result must not be treated as a definite
                # refusal.
                from gateway.relay.egress import declined_send

                _confirm_err = getattr(button_result, "error", None)
                if declined_send(button_result):
                    logger.warning(
                        "slash-confirm DECLINED by the connector's egress "
                        "guard for %s on %s — suppressing the text fallback: %s",
                        command, source.platform, _confirm_err,
                    )
                    _slash_confirm_mod.clear(session_key)
                    return None
            except Exception as exc:
                logger.debug("send_slash_confirm failed for %s on %s: %s", command, source.platform, exc)
        # Text fallback — the prompt message itself is the direct reply.
        return message

    def _read_user_config(self) -> Dict[str, Any]:
        """Raw config.yaml for gate lookups that must see on-disk changes without a restart."""
        try:
            from hermes_cli.config import load_config
            cfg = load_config()
        except Exception:
            return {}
        return cfg if isinstance(cfg, dict) else {}

gateway.warning_notifications:
"""Delivery policy for engine diagnostics, never assistant or command responses."""

from gateway.display_config import resolve_display_setting


class DiagnosticText(str):
    """Producer-owned classification on the legacy two-argument status callback.

    String behavior and event kind stay unchanged for existing plugin renderers.
    Durable carriers must serialize their own category, not this in-memory marker.
    """


def is_warning_status(event_type: str, message: str) -> bool:
    return event_type == "warn" or isinstance(message, DiagnosticText)


def is_diagnostic_notice(notice) -> bool:
    """Out-of-band ``AgentNotice`` classification shared by the gateway, TUI and CLI sinks.

    Credit-service notices are automatic diagnostics at every level (usage bands are ``info``,
    ``credits.restored`` is ``success``); everything else is diagnostic only when it warns.
    """
    return (getattr(notice, "level", None) in {"warn", "error"}
            or str(getattr(notice, "key", "") or "").startswith("credits."))


def diagnostic_metadata(event) -> dict:
    """``{"notification_category": "diagnostic"}`` for a trusted diagnostic-only wake, else ``{}``.

    Only internal wakes may classify a turn; human content never does.
    """
    if getattr(event, "internal", False) and (getattr(event, "metadata", None) or {}).get(
            "notification_category") == "diagnostic":
        return {"notification_category": "diagnostic"}
    return {}


def effective_user_config() -> dict:
    """The active profile's effective config, or ``{}`` when it cannot be read (presentation fails open)."""
    from hermes_cli.config_effective import load_user_config_effective
    try:
        config = load_user_config_effective()
    except Exception:
        return {}
    return config if isinstance(config, dict) else {}


def diagnostic_turn_muted(display_metadata, platform, user_config=None) -> bool:
    """One admission rule for every surface: a diagnostic-category wake mutes its turn's
    presentation only when the owning policy hides diagnostics. Human content never mutes."""
    return ((display_metadata or {}).get("notification_category") == "diagnostic"
            and not warning_notifications_enabled(platform, user_config))


def diagnostic_wake_muted(event, user_config=None) -> bool:
    """Only trusted diagnostic-only wakes can mute a turn, never human content."""
    snapshot = getattr(event, "_notification_reply_muted", None)
    if isinstance(snapshot, bool):
        return snapshot
    return bool(getattr(event, "internal", False)) and diagnostic_turn_muted(
        getattr(event, "metadata", None), event.source.platform, user_config)


def render_notification(render, *, platform, diagnostic=True, user_config=None) -> bool:
    """Invoke a synchronous UI renderer only when its classified content is visible.

    Return whether the renderer ran, not whether a transport delivered anything.
    Call only at a presentation sink, never around producer callbacks or persistence.
    The caller supplies the owning scope/turn snapshot; exceptions remain its policy.
    """
    if diagnostic and not warning_notifications_enabled(platform, user_config):
        return False
    render()
    return True


async def present_notification(present, *, platform, diagnostic=True, user_config=None) -> bool:
    """Async twin of :func:`render_notification` for lifecycle emitters that await a send.

    Return whether the presenter ran; its own receipt/exception is the caller's to interpret.
    The caller binds the owning profile scope BEFORE calling (watchers/shutdown fan-outs).
    """
    if diagnostic and not warning_notifications_enabled(platform, user_config):
        return False
    await present()
    return True


def warning_notifications_enabled(platform, user_config=None) -> bool:
    """Use the turn snapshot when supplied, otherwise the active profile's effective config.

    No surface exemption: direct command/API outcomes are not notifications.
    Unknown values never opt in; null inherits via the canonical display resolver.
    """
    if user_config is None:
        user_config = effective_user_config()
    elif not isinstance(user_config, dict):
        user_config = {}
    platform_key = getattr(platform, "value", platform)
    return not resolve_display_setting(user_config, platform_key, "suppress_warning_notifications", False)
